ALTER TABLE sys_plan ADD COLUMN workspace_enabled boolean NOT NULL DEFAULT true,ADD COLUMN public_form_limit int NOT NULL DEFAULT 5 CHECK(public_form_limit BETWEEN 0 AND 1000),ADD COLUMN public_submission_monthly_limit int NOT NULL DEFAULT 1000 CHECK(public_submission_monthly_limit BETWEEN 0 AND 1000000);
ALTER TABLE crm_custom_field DROP CONSTRAINT IF EXISTS crm_custom_field_entity_type_check;
ALTER TABLE crm_custom_field ADD CONSTRAINT crm_custom_field_entity_type_check CHECK(entity_type IN('CUSTOMER','CONTACT','LEAD','OPPORTUNITY','TICKET','QUOTE','ORDER','CONTRACT','RECEIPT','INVOICE','EXPENSE','TARGET','COMMISSION','WEEKLY','PRODUCT'));
ALTER TABLE crm_custom_value DROP CONSTRAINT IF EXISTS crm_custom_value_entity_type_check;
ALTER TABLE crm_custom_value ADD CONSTRAINT crm_custom_value_entity_type_check CHECK(entity_type IN('CUSTOMER','CONTACT','LEAD','OPPORTUNITY','TICKET','QUOTE','ORDER','CONTRACT','RECEIPT','INVOICE','EXPENSE','TARGET','COMMISSION','WEEKLY','PRODUCT'));
CREATE TABLE crm_object_policy(tenant_id uuid NOT NULL,entity_type varchar(30) NOT NULL,role_code varchar(30) NOT NULL,can_read boolean NOT NULL,can_write boolean NOT NULL,version bigint NOT NULL DEFAULT 0,CHECK(NOT can_write OR can_read),CHECK(role_code<>'VIEWER' OR NOT can_write),PRIMARY KEY(tenant_id,entity_type,role_code),FOREIGN KEY(tenant_id,role_code) REFERENCES sys_role_policy(tenant_id,role_code));
CREATE TABLE crm_workspace_attachment(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,entity_type varchar(30) NOT NULL,record_id uuid NOT NULL,file_name varchar(200) NOT NULL,content_type varchar(100) NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes BETWEEN 1 AND 5242880),sha256 char(64) NOT NULL,object_key varchar(300) NOT NULL UNIQUE,status varchar(20) NOT NULL DEFAULT 'READY' CHECK(status IN('READY','DELETED')),uploaded_by_member_id uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,uploaded_by_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE FUNCTION crm_workspace_storage_usage() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='INSERT' THEN UPDATE sys_tenant SET attachment_bytes=attachment_bytes+NEW.size_bytes WHERE id=NEW.tenant_id;
 ELSIF OLD.status='READY' AND NEW.status='DELETED' THEN UPDATE sys_tenant SET attachment_bytes=attachment_bytes-OLD.size_bytes WHERE id=NEW.tenant_id;END IF;RETURN NEW;END$$;
CREATE TRIGGER workspace_attachment_usage AFTER INSERT OR UPDATE ON crm_workspace_attachment FOR EACH ROW EXECUTE FUNCTION crm_workspace_storage_usage();
CREATE TABLE crm_workspace_notice(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,member_id uuid NOT NULL,entity_type varchar(30) NOT NULL,record_id uuid NOT NULL,title varchar(200) NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_public_form(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,name varchar(100) NOT NULL,entity_type varchar(30) NOT NULL CHECK(entity_type IN('LEAD','TICKET')),owner_member_id uuid NOT NULL,creator_member_id uuid NOT NULL,owner_auth_version bigint NOT NULL,token_hash char(64) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,expires_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,owner_member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_public_submission(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,form_id uuid NOT NULL,request_key varchar(80) NOT NULL,request_hash char(64) NOT NULL,fingerprint char(64) NOT NULL,entity_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,form_id,request_key),FOREIGN KEY(tenant_id,form_id) REFERENCES crm_public_form(tenant_id,id));
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['crm_object_policy','crm_workspace_attachment','crm_workspace_notice','crm_public_form','crm_public_submission'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_boundary ON %I USING(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid)',n);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON crm_object_policy,crm_workspace_attachment,crm_workspace_notice,crm_public_form TO crm_runtime;
GRANT SELECT,INSERT ON crm_public_submission TO crm_runtime;
DO $$DECLARE n text;ev text;BEGIN FOR n,ev IN SELECT * FROM(VALUES('crm_quote','quote'),('crm_sales_order','order'),('crm_contract','contract'),('crm_invoice','invoice'),('crm_expense','expense'),('crm_sales_target','target'),('crm_commission_run','commission'),('crm_sales_weekly_report','weekly')) v(n,ev) LOOP EXECUTE format('CREATE TRIGGER extended_webhook AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION crm_enqueue_webhook(%L)',n,ev);END LOOP;END$$;
